    def test_bound_save_updates_in_place(self, collection: Collection) -> None:
        stored = self.add_task(collection, summary="before")
        first_etag = stored.etag
        stored.component["SUMMARY"] = "after"
        stored.save()
        assert stored.etag != first_etag
        stored.component["SUMMARY"] = "after again"
        stored.save()  # no stale etag
        assert str((collection.get_by_native_id(nid(stored))).component["SUMMARY"]) == "after again"

    def test_collection_save_returns_a_copy(self, collection: Collection) -> None:
        stored = self.add_task(collection, summary="before")
        etag = stored.etag
        stored.component["SUMMARY"] = "after"
        result = collection.save(stored)
        assert result is not stored
        assert stored.etag == etag, "collection.save() changed its argument"
        assert result.etag != etag
        assert isinstance(result, SyncTask)

    def test_save_detects_conflicts(self, collection: Collection) -> None:
        mine = self.add_task(collection, summary="original")
        theirs = collection.get_by_native_id(nid(mine))
        theirs.component["SUMMARY"] = "theirs"
        theirs.save()
        mine.component["SUMMARY"] = "mine"
        with pytest.raises(ConflictError) as info:
            mine.save()
        assert not isinstance(info.value, AlreadyExistsError | SyncTokenError)
        assert str((collection.reload(mine)).component["SUMMARY"]) == "theirs"
        mine.save(overwrite=True)
        assert str((collection.reload(mine)).component["SUMMARY"]) == "mine"

    def test_delete(self, collection: Collection) -> None:
        stored = self.add_task(collection, summary="doomed")
        stale = collection.get_by_native_id(nid(stored))
        stored.component["SUMMARY"] = "changed"
        stored.save()
        with pytest.raises(ConflictError):
            collection.delete(stale)
        stored.delete()
        with pytest.raises(NotFoundError):
            collection.get_by_native_id(nid(stored))
        other = collection.add_task(summary="by id")
        collection.delete(nid(other))
        with pytest.raises(NotFoundError):
            collection.get(other.uid)

    def test_read_only_rejects_every_write(self, backend: Backend, collection: Collection) -> None:
        if writable(collection):
            return
        kinds = [k for k in KINDS if holds(collection, k)]
        if not kinds:
            pytest.fail("a read-only collection that holds nothing")
        [stored] = self.seed(collection, [KINDS[kinds[0]][0].new(summary="seeded")])
        other = self.open_collection(backend, "conformance-other")
        for call in (
            lambda: collection.add(Task.new(summary="x")),
            lambda: collection.save(stored),
            lambda: stored.save(),
            lambda: collection.delete(stored),
            lambda: collection.move(stored, other),
        ):
            self.assert_unsupported(collection, Feature.WRITE, call)
        if isinstance(stored, SyncTask):
            self.assert_unsupported(collection, Feature.WRITE, lambda: stored.complete())

